INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('1358cf58-4f2c-4c5a-83ef-f7acabd04683', 'a2fb932f-2af6-4ba4-9a86-3cc1259406cb', 'Coordinate Geometry', 0, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('338dcc07-190b-4bfc-a5e7-7561efacc616', '1358cf58-4f2c-4c5a-83ef-f7acabd04683', 'The Equation of a Straight Line', 'text', '{"html": "\n                                <h3>Understanding the Line Equation</h3>\n                                <p>The general equation of a straight line is given by:</p>\n                                \\[ y = mx + c \\]\n                                <p>Where:</p>\n                                <ul>\n                                    <li><strong>m</strong> is the gradient (slope)</li>\n                                    <li><strong>c</strong> is the y-intercept (where the line crosses the y-axis)</li>\n                                </ul>\n                                <h3>Example 1: Finding Gradient and Intercept</h3>\n                                <p>Given the equation \\( y = 2x + 3 \\):</p>\n                                <ul>\n                                    <li>Gradient \\( m = 2 \\)</li>\n                                    <li>Y-intercept \\( c = 3 \\)</li>\n                                </ul>\n                                <h3>Example 2: Rearranging Equations</h3>\n                                <p>Sometimes equations aren''t in the form \\( y = mx + c \\). Let''s rearrange \\( 2y - 4x = 8 \\):</p>\n                                <p>Step 1: Add \\( 4x \\) to both sides:</p>\n                                \\[ 2y = 4x + 8 \\]\n                                <p>Step 2: Divide by 2:</p>\n                                \\[ y = 2x + 4 \\]\n                                <p>Now we can see \\( m = 2 \\) and \\( c = 4 \\).</p>\n                            ", "blocks": [{"id": "ba4127b3-25c2-48f9-8d30-29cf90092ba0", "type": "text", "content": "\n                                <h3>Understanding the Line Equation</h3>\n                                <p>The general equation of a straight line is given by:</p>\n                                \\[ y = mx + c \\]\n                                <p>Where:</p>\n                                <ul>\n                                    <li><strong>m</strong> is the gradient (slope)</li>\n                                    <li><strong>c</strong> is the y-intercept (where the line crosses the y-axis)</li>\n                                </ul>\n                                <h3>Example 1: Finding Gradient and Intercept</h3>\n                                <p>Given the equation \\( y = 2x + 3 \\):</p>\n                                <ul>\n                                    <li>Gradient \\( m = 2 \\)</li>\n                                    <li>Y-intercept \\( c = 3 \\)</li>\n                                </ul>\n                                <h3>Example 2: Rearranging Equations</h3>\n                                <p>Sometimes equations aren''t in the form \\( y = mx + c \\). Let''s rearrange \\( 2y - 4x = 8 \\):</p>\n                                <p>Step 1: Add \\( 4x \\) to both sides:</p>\n                                \\[ 2y = 4x + 8 \\]\n                                <p>Step 2: Divide by 2:</p>\n                                \\[ y = 2x + 4 \\]\n                                <p>Now we can see \\( m = 2 \\) and \\( c = 4 \\).</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('276b4bad-f4f1-467d-a612-a645834c8d6d', '1358cf58-4f2c-4c5a-83ef-f7acabd04683', 'Calculating Gradients', 'text', '{"html": "\n                                <h3>The Gradient Formula</h3>\n                                <p>The gradient \\( m \\) of a line passing through two points \\( (x_1, y_1) \\) and \\( (x_2, y_2) \\) is:</p>\n                                \\[ m = \\frac{y_2 - y_1}{x_2 - x_1} \\]\n                                <h3>Worked Example</h3>\n                                <p>Find the gradient of the line passing through A(2, 4) and B(6, 12).</p>\n                                <p><strong>Solution:</strong></p>\n                                <p>Let \\( (x_1, y_1) = (2, 4) \\) and \\( (x_2, y_2) = (6, 12) \\).</p>\n                                \\[ m = \\frac{12 - 4}{6 - 2} \\]\n                                \\[ m = \\frac{8}{4} \\]\n                                \\[ m = 2 \\]\n                                <p>The gradient is 2.</p>\n                            ", "blocks": [{"id": "ae542633-a673-43e2-a7d7-90d0409c0c2a", "type": "text", "content": "\n                                <h3>The Gradient Formula</h3>\n                                <p>The gradient \\( m \\) of a line passing through two points \\( (x_1, y_1) \\) and \\( (x_2, y_2) \\) is:</p>\n                                \\[ m = \\frac{y_2 - y_1}{x_2 - x_1} \\]\n                                <h3>Worked Example</h3>\n                                <p>Find the gradient of the line passing through A(2, 4) and B(6, 12).</p>\n                                <p><strong>Solution:</strong></p>\n                                <p>Let \\( (x_1, y_1) = (2, 4) \\) and \\( (x_2, y_2) = (6, 12) \\).</p>\n                                \\[ m = \\frac{12 - 4}{6 - 2} \\]\n                                \\[ m = \\frac{8}{4} \\]\n                                \\[ m = 2 \\]\n                                <p>The gradient is 2.</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('24a64423-8df1-410b-85ee-e816642a1a21', '1358cf58-4f2c-4c5a-83ef-f7acabd04683', 'Parallel and Perpendicular Lines', 'text', '{"html": "\n                                <h3>Parallel Lines</h3>\n                                <p>Two lines are parallel if they have the <strong>same gradient</strong>.</p>\n                                <p>Example: \\( y = 3x + 1 \\) and \\( y = 3x - 5 \\) are parallel because \\( m = 3 \\) for both.</p>\n                                <h3>Perpendicular Lines</h3>\n                                <p>Two lines are perpendicular if the product of their gradients is -1:</p>\n                                \\[ m_1 \\times m_2 = -1 \\]\n                                <p>Or:</p>\n                                \\[ m_2 = -\\frac{1}{m_1} \\]\n                                <h3>Worked Example</h3>\n                                <p>Find the equation of a line perpendicular to \\( y = 2x + 1 \\) passing through (0, 0).</p>\n                                <p><strong>Solution:</strong></p>\n                                <p>1. Gradient of original line \\( m_1 = 2 \\).</p>\n                                <p>2. Gradient of perpendicular line \\( m_2 = -\\frac{1}{2} \\).</p>\n                                <p>3. Equation: \\( y = -\\frac{1}{2}x + c \\).</p>\n                                <p>4. Since it passes through (0, 0), \\( c = 0 \\).</p>\n                                <p>Final Equation: \\( y = -\\frac{1}{2}x \\)</p>\n                            ", "blocks": [{"id": "3a822cbe-afbe-4289-8b87-4b6368d7555e", "type": "text", "content": "\n                                <h3>Parallel Lines</h3>\n                                <p>Two lines are parallel if they have the <strong>same gradient</strong>.</p>\n                                <p>Example: \\( y = 3x + 1 \\) and \\( y = 3x - 5 \\) are parallel because \\( m = 3 \\) for both.</p>\n                                <h3>Perpendicular Lines</h3>\n                                <p>Two lines are perpendicular if the product of their gradients is -1:</p>\n                                \\[ m_1 \\times m_2 = -1 \\]\n                                <p>Or:</p>\n                                \\[ m_2 = -\\frac{1}{m_1} \\]\n                                <h3>Worked Example</h3>\n                                <p>Find the equation of a line perpendicular to \\( y = 2x + 1 \\) passing through (0, 0).</p>\n                                <p><strong>Solution:</strong></p>\n                                <p>1. Gradient of original line \\( m_1 = 2 \\).</p>\n                                <p>2. Gradient of perpendicular line \\( m_2 = -\\frac{1}{2} \\).</p>\n                                <p>3. Equation: \\( y = -\\frac{1}{2}x + c \\).</p>\n                                <p>4. Since it passes through (0, 0), \\( c = 0 \\).</p>\n                                <p>Final Equation: \\( y = -\\frac{1}{2}x \\)</p>\n                            ", "order": 0}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('1f7f1561-a219-46cd-8272-f2c4b3bbe5de', '1358cf58-4f2c-4c5a-83ef-f7acabd04683', 'Midpoint and Distance', 'text', '{"html": "\n                                <h3>Midpoint Formula</h3>\n                                <p>The midpoint \\( M \\) between \\( (x_1, y_1) \\) and \\( (x_2, y_2) \\) is:</p>\n                                \\[ M = \\left( \\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2} \\right) \\]\n                                <h3>Distance Formula</h3>\n                                <p>The distance \\( d \\) between two points is derived from Pythagoras'' theorem:</p>\n                                \\[ d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2} \\]\n                                <h3>Practice Problem</h3>\n                                <p>Find the distance between P(1, 1) and Q(4, 5).</p>\n                                \\[ d = \\sqrt{(4 - 1)^2 + (5 - 1)^2} \\]\n                                \\[ d = \\sqrt{3^2 + 4^2} \\]\n                                \\[ d = \\sqrt{9 + 16} = \\sqrt{25} = 5 \\]\n                            ", "blocks": [{"id": "8c205133-a182-4630-8e71-a65bd242372a", "type": "text", "content": "\n                                <h3>Midpoint Formula</h3>\n                                <p>The midpoint \\( M \\) between \\( (x_1, y_1) \\) and \\( (x_2, y_2) \\) is:</p>\n                                \\[ M = \\left( \\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2} \\right) \\]\n                                <h3>Distance Formula</h3>\n                                <p>The distance \\( d \\) between two points is derived from Pythagoras'' theorem:</p>\n                                \\[ d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2} \\]\n                                <h3>Practice Problem</h3>\n                                <p>Find the distance between P(1, 1) and Q(4, 5).</p>\n                                \\[ d = \\sqrt{(4 - 1)^2 + (5 - 1)^2} \\]\n                                \\[ d = \\sqrt{3^2 + 4^2} \\]\n                                \\[ d = \\sqrt{9 + 16} = \\sqrt{25} = 5 \\]\n                            ", "order": 0}]}', 3, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('9975467c-f38e-4a46-a83b-d22571838318', 'a2fb932f-2af6-4ba4-9a86-3cc1259406cb', 'Simultaneous Equations', 1, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('9c1ae83b-b494-454e-96ad-9320af894d13', '9975467c-f38e-4a46-a83b-d22571838318', 'Substitution Method', 'text', '{"html": "\n                                <h3>Introduction</h3>\n                                <p>The substitution method involves solving one equation for one variable and substituting it into the other.</p>\n                                <h3>Example</h3>\n                                <p>Solve:</p>\n                                <ol>\n                                    <li>\\( y = x + 2 \\)</li>\n                                    <li>\\( 2x + y = 11 \\)</li>\n                                </ol>\n                                <p><strong>Step 1:</strong> Substitute (1) into (2):</p>\n                                \\[ 2x + (x + 2) = 11 \\]\n                                \\[ 3x + 2 = 11 \\]\n                                <p><strong>Step 2:</strong> Solve for x:</p>\n                                \\[ 3x = 9 \\implies x = 3 \\]\n                                <p><strong>Step 3:</strong> Substitute x back into (1):</p>\n                                \\[ y = 3 + 2 = 5 \\]\n                                <p><strong>Solution:</strong> \\( x = 3, y = 5 \\)</p>\n                            ", "blocks": [{"id": "277cfdf2-6bc6-43ad-9c2c-cffbbea17140", "type": "text", "content": "\n                                <h3>Introduction</h3>\n                                <p>The substitution method involves solving one equation for one variable and substituting it into the other.</p>\n                                <h3>Example</h3>\n                                <p>Solve:</p>\n                                <ol>\n                                    <li>\\( y = x + 2 \\)</li>\n                                    <li>\\( 2x + y = 11 \\)</li>\n                                </ol>\n                                <p><strong>Step 1:</strong> Substitute (1) into (2):</p>\n                                \\[ 2x + (x + 2) = 11 \\]\n                                \\[ 3x + 2 = 11 \\]\n                                <p><strong>Step 2:</strong> Solve for x:</p>\n                                \\[ 3x = 9 \\implies x = 3 \\]\n                                <p><strong>Step 3:</strong> Substitute x back into (1):</p>\n                                \\[ y = 3 + 2 = 5 \\]\n                                <p><strong>Solution:</strong> \\( x = 3, y = 5 \\)</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('f3882678-8173-470b-befd-bfcfffa6bc3d', '9975467c-f38e-4a46-a83b-d22571838318', 'Elimination Method', 'text', '{"html": "\n                                <h3>Introduction</h3>\n                                <p>The elimination method involves adding or subtracting equations to remove one variable.</p>\n                                <h3>Example</h3>\n                                <p>Solve:</p>\n                                <ol>\n                                    <li>\\( 3x + 2y = 12 \\)</li>\n                                    <li>\\( 3x - y = 3 \\)</li>\n                                </ol>\n                                <p><strong>Step 1:</strong> Subtract (2) from (1) to eliminate x:</p>\n                                \\[ (3x - 3x) + (2y - (-y)) = 12 - 3 \\]\n                                \\[ 3y = 9 \\]\n                                \\[ y = 3 \\]\n                                <p><strong>Step 2:</strong> Substitute y = 3 into (2):</p>\n                                \\[ 3x - 3 = 3 \\]\n                                \\[ 3x = 6 \\implies x = 2 \\]\n                                <p><strong>Solution:</strong> \\( x = 2, y = 3 \\)</p>\n                            ", "blocks": [{"id": "644e6570-3a8f-41ff-ab52-139b2f69e0bd", "type": "text", "content": "\n                                <h3>Introduction</h3>\n                                <p>The elimination method involves adding or subtracting equations to remove one variable.</p>\n                                <h3>Example</h3>\n                                <p>Solve:</p>\n                                <ol>\n                                    <li>\\( 3x + 2y = 12 \\)</li>\n                                    <li>\\( 3x - y = 3 \\)</li>\n                                </ol>\n                                <p><strong>Step 1:</strong> Subtract (2) from (1) to eliminate x:</p>\n                                \\[ (3x - 3x) + (2y - (-y)) = 12 - 3 \\]\n                                \\[ 3y = 9 \\]\n                                \\[ y = 3 \\]\n                                <p><strong>Step 2:</strong> Substitute y = 3 into (2):</p>\n                                \\[ 3x - 3 = 3 \\]\n                                \\[ 3x = 6 \\implies x = 2 \\]\n                                <p><strong>Solution:</strong> \\( x = 2, y = 3 \\)</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('4400f8bb-a4e9-4dc8-8a35-e6d34ea9b56e', '9975467c-f38e-4a46-a83b-d22571838318', 'Graphical Method', 'text', '{"html": "\n                                <h3>Visualizing Solutions</h3>\n                                <p>Simultaneous equations represent lines. The solution is the point where they intersect.</p>\n                                <p>To solve graphically:</p>\n                                <ol>\n                                    <li>Plot the first line.</li>\n                                    <li>Plot the second line.</li>\n                                    <li>Read the coordinates of the intersection point.</li>\n                                </ol>\n                                <p>If the lines are parallel, there is no solution. If they are the same line, there are infinite solutions.</p>\n                            ", "blocks": [{"id": "e480f5cb-0345-4d31-ab69-bb330057505f", "type": "text", "content": "\n                                <h3>Visualizing Solutions</h3>\n                                <p>Simultaneous equations represent lines. The solution is the point where they intersect.</p>\n                                <p>To solve graphically:</p>\n                                <ol>\n                                    <li>Plot the first line.</li>\n                                    <li>Plot the second line.</li>\n                                    <li>Read the coordinates of the intersection point.</li>\n                                </ol>\n                                <p>If the lines are parallel, there is no solution. If they are the same line, there are infinite solutions.</p>\n                            ", "order": 0}, {"id": "graph-simul-eq", "type": "graph", "title": "Interactive Graph: y = x + 2 and 2x + y = 11", "data": {"functions": [{"fn": "x + 2", "color": "blue"}, {"fn": "-2x + 11", "color": "red"}], "xDomain": [-5, 10], "yDomain": [-5, 15]}, "order": 1}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('2fb6f32c-17f6-4667-bc64-2dcf07af1f6f', 'a2fb932f-2af6-4ba4-9a86-3cc1259406cb', 'Quadratic Functions', 2, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('0e8e3e5c-63dc-4069-9466-f41d19d2d52f', '2fb6f32c-17f6-4667-bc64-2dcf07af1f6f', 'Factorising Quadratics', 'text', '{"html": "\n                                <h3>Standard Form</h3>\n                                <p>A quadratic is in the form \\( ax^2 + bx + c \\).</p>\n                                <h3>Factorising \\( x^2 + bx + c \\)</h3>\n                                <p>Find two numbers that multiply to give \\( c \\) and add to give \\( b \\).</p>\n                                <p><strong>Example:</strong> Factorise \\( x^2 + 5x + 6 \\)</p>\n                                <ul>\n                                    <li>Factors of 6: 1 & 6, 2 & 3.</li>\n                                    <li>2 + 3 = 5.</li>\n                                </ul>\n                                <p>So, \\( (x + 2)(x + 3) \\).</p>\n                            ", "blocks": [{"id": "e38a4407-0cf0-4c5a-9351-c69dbf57c8e9", "type": "text", "content": "\n                                <h3>Standard Form</h3>\n                                <p>A quadratic is in the form \\( ax^2 + bx + c \\).</p>\n                                <h3>Factorising \\( x^2 + bx + c \\)</h3>\n                                <p>Find two numbers that multiply to give \\( c \\) and add to give \\( b \\).</p>\n                                <p><strong>Example:</strong> Factorise \\( x^2 + 5x + 6 \\)</p>\n                                <ul>\n                                    <li>Factors of 6: 1 & 6, 2 & 3.</li>\n                                    <li>2 + 3 = 5.</li>\n                                </ul>\n                                <p>So, \\( (x + 2)(x + 3) \\).</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('d1a0b502-9e87-4ea2-aba3-a78477ded7e0', '2fb6f32c-17f6-4667-bc64-2dcf07af1f6f', 'The Quadratic Formula', 'text', '{"html": "\n                                <h3>The Formula</h3>\n                                <p>For \\( ax^2 + bx + c = 0 \\), the solutions are:</p>\n                                \\[ x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} \\]\n                                <h3>Example</h3>\n                                <p>Solve \\( 2x^2 + 5x - 3 = 0 \\).</p>\n                                <p>\\( a = 2, b = 5, c = -3 \\)</p>\n                                \\[ x = \\frac{-5 \\pm \\sqrt{5^2 - 4(2)(-3)}}{2(2)} \\]\n                                \\[ x = \\frac{-5 \\pm \\sqrt{25 + 24}}{4} \\]\n                                \\[ x = \\frac{-5 \\pm \\sqrt{49}}{4} \\]\n                                \\[ x = \\frac{-5 \\pm 7}{4} \\]\n                                <p>Solutions:</p>\n                                \\[ x_1 = \\frac{2}{4} = 0.5, \\quad x_2 = \\frac{-12}{4} = -3 \\]\n                            ", "blocks": [{"id": "30e41ad8-6f66-4367-ab63-6fd2a404452d", "type": "text", "content": "\n                                <h3>The Formula</h3>\n                                <p>For \\( ax^2 + bx + c = 0 \\), the solutions are:</p>\n                                \\[ x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} \\]\n                                <h3>Example</h3>\n                                <p>Solve \\( 2x^2 + 5x - 3 = 0 \\).</p>\n                                <p>\\( a = 2, b = 5, c = -3 \\)</p>\n                                \\[ x = \\frac{-5 \\pm \\sqrt{5^2 - 4(2)(-3)}}{2(2)} \\]\n                                \\[ x = \\frac{-5 \\pm \\sqrt{25 + 24}}{4} \\]\n                                \\[ x = \\frac{-5 \\pm \\sqrt{49}}{4} \\]\n                                \\[ x = \\frac{-5 \\pm 7}{4} \\]\n                                <p>Solutions:</p>\n                                \\[ x_1 = \\frac{2}{4} = 0.5, \\quad x_2 = \\frac{-12}{4} = -3 \\]\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('583bcbd9-2ae9-4a0f-be6c-f094deb14a19', '2fb6f32c-17f6-4667-bc64-2dcf07af1f6f', 'Completing the Square', 'text', '{"html": "\n                                <h3>Method</h3>\n                                <p>To express \\( x^2 + bx \\) as a perfect square:</p>\n                                \\[ \\left(x + \\frac{b}{2}\\right)^2 - \\left(\\frac{b}{2}\\right)^2 \\]\n                                <h3>Example</h3>\n                                <p>Complete the square for \\( x^2 + 6x + 5 \\).</p>\n                                \\[ (x + 3)^2 - 3^2 + 5 \\]\n                                \\[ (x + 3)^2 - 9 + 5 \\]\n                                \\[ (x + 3)^2 - 4 \\]\n                                <p>This form helps find the turning point (vertex) of the parabola. Here, the minimum point is (-3, -4).</p>\n                            ", "blocks": [{"id": "ab7bac6c-66d9-49b4-8a6c-b5c0afc869cf", "type": "text", "content": "\n                                <h3>Method</h3>\n                                <p>To express \\( x^2 + bx \\) as a perfect square:</p>\n                                \\[ \\left(x + \\frac{b}{2}\\right)^2 - \\left(\\frac{b}{2}\\right)^2 \\]\n                                <h3>Example</h3>\n                                <p>Complete the square for \\( x^2 + 6x + 5 \\).</p>\n                                \\[ (x + 3)^2 - 3^2 + 5 \\]\n                                \\[ (x + 3)^2 - 9 + 5 \\]\n                                \\[ (x + 3)^2 - 4 \\]\n                                <p>This form helps find the turning point (vertex) of the parabola. Here, the minimum point is (-3, -4).</p>\n                            ", "order": 0}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('4123d748-7255-471e-b55f-8fb1bff8ca66', 'a2fb932f-2af6-4ba4-9a86-3cc1259406cb', 'Inequalities', 3, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('2e03442c-aa9b-42a5-adee-11be825f8fa3', '4123d748-7255-471e-b55f-8fb1bff8ca66', 'Linear Inequalities', 'text', '{"html": "\n                                <h3>Solving Basic Inequalities</h3>\n                                <p>Treat the inequality sign like an equals sign, but remember: <strong>flip the sign when multiplying or dividing by a negative number</strong>.</p>\n                                <h3>Example</h3>\n                                <p>Solve \\( 3 - 2x > 7 \\).</p>\n                                \\[ -2x > 4 \\]\n                                <p>Divide by -2 (flip sign):</p>\n                                \\[ x < -2 \\]\n                                <h3>Number Line Representation</h3>\n                                <p>An open circle means \\( < \\) or \\( > \\). A filled circle means \\( \\leq \\) or \\( \\geq \\).</p>\n                            ", "blocks": [{"id": "dbe584bf-c7e9-4be4-9f30-17a1d2d0a9ba", "type": "text", "content": "\n                                <h3>Solving Basic Inequalities</h3>\n                                <p>Treat the inequality sign like an equals sign, but remember: <strong>flip the sign when multiplying or dividing by a negative number</strong>.</p>\n                                <h3>Example</h3>\n                                <p>Solve \\( 3 - 2x > 7 \\).</p>\n                                \\[ -2x > 4 \\]\n                                <p>Divide by -2 (flip sign):</p>\n                                \\[ x < -2 \\]\n                                <h3>Number Line Representation</h3>\n                                <p>An open circle means \\( < \\) or \\( > \\). A filled circle means \\( \\leq \\) or \\( \\geq \\).</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('e9f97225-556f-466b-a135-9550a95beeba', '4123d748-7255-471e-b55f-8fb1bff8ca66', 'Quadratic Inequalities', 'text', '{"html": "\n                                <h3>Steps to Solve</h3>\n                                <ol>\n                                    <li>Find the critical values (roots) by solving the equation equal to zero.</li>\n                                    <li>Sketch the quadratic curve.</li>\n                                    <li>Determine the region where the curve is above (> 0) or below (< 0) the x-axis.</li>\n                                </ol>\n                                <h3>Example</h3>\n                                <p>Solve \\( x^2 - 4 < 0 \\).</p>\n                                <p>Roots: \\( x^2 = 4 \\implies x = \\pm 2 \\).</p>\n                                <p>Sketch: U-shaped parabola crossing at -2 and 2.</p>\n                                <p>We want where it is less than 0 (below axis).</p>\n                                <p><strong>Solution:</strong> \\( -2 < x < 2 \\)</p>\n                            ", "blocks": [{"id": "e25f9742-bf02-4008-bc29-26f49a2fc251", "type": "text", "content": "\n                                <h3>Steps to Solve</h3>\n                                <ol>\n                                    <li>Find the critical values (roots) by solving the equation equal to zero.</li>\n                                    <li>Sketch the quadratic curve.</li>\n                                    <li>Determine the region where the curve is above (> 0) or below (< 0) the x-axis.</li>\n                                </ol>\n                                <h3>Example</h3>\n                                <p>Solve \\( x^2 - 4 < 0 \\).</p>\n                                <p>Roots: \\( x^2 = 4 \\implies x = \\pm 2 \\).</p>\n                                <p>Sketch: U-shaped parabola crossing at -2 and 2.</p>\n                                <p>We want where it is less than 0 (below axis).</p>\n                                <p><strong>Solution:</strong> \\( -2 < x < 2 \\)</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('82d86037-d9be-4b99-aa29-f12ba8bebc24', 'a2fb932f-2af6-4ba4-9a86-3cc1259406cb', 'Real-Life Graphs', 4, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('65a4719d-3e0b-4eed-bb6f-6faa668a017c', '82d86037-d9be-4b99-aa29-f12ba8bebc24', 'Distance-Time Graphs', 'text', '{"html": "\n                                <h3>Interpreting the Graph</h3>\n                                <ul>\n                                    <li><strong>Gradient:</strong> Represents Speed.</li>\n                                    <li><strong>Flat line:</strong> Object is stationary.</li>\n                                    <li><strong>Steeper line:</strong> Faster speed.</li>\n                                </ul>\n                                <h3>Calculating Speed</h3>\n                                <p>Speed = Gradient = \\( \\frac{\\text{Change in Distance}}{\\text{Change in Time}} \\).</p>\n                            ", "blocks": [{"id": "db38f2a8-8f67-46d9-8995-a43e4f0f9f8c", "type": "text", "content": "\n                                <h3>Interpreting the Graph</h3>\n                                <ul>\n                                    <li><strong>Gradient:</strong> Represents Speed.</li>\n                                    <li><strong>Flat line:</strong> Object is stationary.</li>\n                                    <li><strong>Steeper line:</strong> Faster speed.</li>\n                                </ul>\n                                <h3>Calculating Speed</h3>\n                                <p>Speed = Gradient = \\( \\frac{\\text{Change in Distance}}{\\text{Change in Time}} \\).</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('ab51c3eb-d5e5-4be9-8c6b-25bf8d75290e', '82d86037-d9be-4b99-aa29-f12ba8bebc24', 'Speed-Time Graphs', 'text', '{"html": "\n                                <h3>Key Features</h3>\n                                <ul>\n                                    <li><strong>Gradient:</strong> Represents Acceleration.</li>\n                                    <li><strong>Area under graph:</strong> Represents Distance travelled.</li>\n                                </ul>\n                                <h3>Example</h3>\n                                <p>A car accelerates from 0 to 20 m/s in 10 seconds. Find acceleration.</p>\n                                \\[ a = \\frac{20 - 0}{10} = 2 \\, \\text{m/s}^2 \\]\n                            ", "blocks": [{"id": "29e80ccb-0a4b-4b35-86fc-6151c15c27e7", "type": "text", "content": "\n                                <h3>Key Features</h3>\n                                <ul>\n                                    <li><strong>Gradient:</strong> Represents Acceleration.</li>\n                                    <li><strong>Area under graph:</strong> Represents Distance travelled.</li>\n                                </ul>\n                                <h3>Example</h3>\n                                <p>A car accelerates from 0 to 20 m/s in 10 seconds. Find acceleration.</p>\n                                \\[ a = \\frac{20 - 0}{10} = 2 \\, \\text{m/s}^2 \\]\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO courses (id, title, description, created_by, status, visibility, level, language, price, created_at, updated_at) VALUES
('5422b24e-1acc-4c1d-bb87-4d291296546a', 'O Level Mathematics: Geometry & Trigonometry', 'Master geometric properties, angles, and trigonometric ratios. Includes comprehensive coverage of mensuration and vectors.', (SELECT id FROM users WHERE email = 'admin@test.com' LIMIT 1), 'published', 'public', 'intermediate', 'en', 0, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('410d0088-9049-428d-af20-f9acdf0ccb2d', '5422b24e-1acc-4c1d-bb87-4d291296546a', 'Angles and Polygons', 0, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('c52c892d-9b33-49e3-8539-0573939daedf', '410d0088-9049-428d-af20-f9acdf0ccb2d', 'Angle Properties', 'text', '{"html": "\n                                <h3>Basic Rules</h3>\n                                <ul>\n                                    <li>Angles on a straight line add to 180\u00b0.</li>\n                                    <li>Angles around a point add to 360\u00b0.</li>\n                                    <li>Vertically opposite angles are equal.</li>\n                                </ul>\n                                <h3>Parallel Lines</h3>\n                                <ul>\n                                    <li><strong>Alternate angles</strong> (Z-shape) are equal.</li>\n                                    <li><strong>Corresponding angles</strong> (F-shape) are equal.</li>\n                                    <li><strong>Co-interior angles</strong> (C-shape) add to 180\u00b0.</li>\n                                </ul>\n                            ", "blocks": [{"id": "1ba6a786-d513-45a4-8f3a-282914a94f59", "type": "text", "content": "\n                                <h3>Basic Rules</h3>\n                                <ul>\n                                    <li>Angles on a straight line add to 180\u00b0.</li>\n                                    <li>Angles around a point add to 360\u00b0.</li>\n                                    <li>Vertically opposite angles are equal.</li>\n                                </ul>\n                                <h3>Parallel Lines</h3>\n                                <ul>\n                                    <li><strong>Alternate angles</strong> (Z-shape) are equal.</li>\n                                    <li><strong>Corresponding angles</strong> (F-shape) are equal.</li>\n                                    <li><strong>Co-interior angles</strong> (C-shape) add to 180\u00b0.</li>\n                                </ul>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('d28e9aca-1ef5-4a7e-b9cf-45c18774f359', '410d0088-9049-428d-af20-f9acdf0ccb2d', 'Polygons', 'text', '{"html": "\n                                <h3>Sum of Interior Angles</h3>\n                                <p>For an n-sided polygon, sum = \\( (n-2) \\times 180^\\circ \\).</p>\n                                <h3>Exterior Angles</h3>\n                                <p>Sum of exterior angles is always 360\u00b0.</p>\n                                <h3>Regular Polygons</h3>\n                                <p>Each exterior angle = \\( \\frac{360}{n} \\).</p>\n                                <p>Each interior angle = \\( 180 - \\text{exterior angle} \\).</p>\n                            ", "blocks": [{"id": "243a3b6b-c01d-4417-b975-36e0e3fcf6bc", "type": "text", "content": "\n                                <h3>Sum of Interior Angles</h3>\n                                <p>For an n-sided polygon, sum = \\( (n-2) \\times 180^\\circ \\).</p>\n                                <h3>Exterior Angles</h3>\n                                <p>Sum of exterior angles is always 360\u00b0.</p>\n                                <h3>Regular Polygons</h3>\n                                <p>Each exterior angle = \\( \\frac{360}{n} \\).</p>\n                                <p>Each interior angle = \\( 180 - \\text{exterior angle} \\).</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('977e6705-e9ed-4aee-8e8a-ceefbbf27969', '410d0088-9049-428d-af20-f9acdf0ccb2d', 'Circle Theorems', 'text', '{"html": "\n                                <h3>Key Theorems</h3>\n                                <ol>\n                                    <li>Angle at center is twice angle at circumference.</li>\n                                    <li>Angle in a semicircle is 90\u00b0.</li>\n                                    <li>Angles in the same segment are equal.</li>\n                                    <li>Opposite angles in a cyclic quadrilateral sum to 180\u00b0.</li>\n                                    <li>Tangent is perpendicular to radius.</li>\n                                </ol>\n                            ", "blocks": [{"id": "96567bd7-a512-4262-8886-2fab717b7900", "type": "text", "content": "\n                                <h3>Key Theorems</h3>\n                                <ol>\n                                    <li>Angle at center is twice angle at circumference.</li>\n                                    <li>Angle in a semicircle is 90\u00b0.</li>\n                                    <li>Angles in the same segment are equal.</li>\n                                    <li>Opposite angles in a cyclic quadrilateral sum to 180\u00b0.</li>\n                                    <li>Tangent is perpendicular to radius.</li>\n                                </ol>\n                            ", "order": 0}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('dac7878f-8c46-44f8-abe1-adacb5a8bd29', '5422b24e-1acc-4c1d-bb87-4d291296546a', 'Trigonometry', 1, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('a11eeef9-6cae-40b9-b749-b907d3033467', 'dac7878f-8c46-44f8-abe1-adacb5a8bd29', 'Right-Angled Triangles (SOHCAHTOA)', 'text', '{"html": "\n                                <h3>Ratios</h3>\n                                <ul>\n                                    <li>\\( \\sin \\theta = \\frac{\\text{Opposite}}{\\text{Hypotenuse}} \\)</li>\n                                    <li>\\( \\cos \\theta = \\frac{\\text{Adjacent}}{\\text{Hypotenuse}} \\)</li>\n                                    <li>\\( \\tan \\theta = \\frac{\\text{Opposite}}{\\text{Adjacent}} \\)</li>\n                                </ul>\n                                <h3>Example</h3>\n                                <p>Find x if \\( \\sin(30^\\circ) = \\frac{x}{10} \\).</p>\n                                \\[ x = 10 \\times \\sin(30^\\circ) = 10 \\times 0.5 = 5 \\]\n                            ", "blocks": [{"id": "3c447b51-5675-404a-981d-c962b35cf8dd", "type": "text", "content": "\n                                <h3>Ratios</h3>\n                                <ul>\n                                    <li>\\( \\sin \\theta = \\frac{\\text{Opposite}}{\\text{Hypotenuse}} \\)</li>\n                                    <li>\\( \\cos \\theta = \\frac{\\text{Adjacent}}{\\text{Hypotenuse}} \\)</li>\n                                    <li>\\( \\tan \\theta = \\frac{\\text{Opposite}}{\\text{Adjacent}} \\)</li>\n                                </ul>\n                                <h3>Example</h3>\n                                <p>Find x if \\( \\sin(30^\\circ) = \\frac{x}{10} \\).</p>\n                                \\[ x = 10 \\times \\sin(30^\\circ) = 10 \\times 0.5 = 5 \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('2bd7ab7b-041d-4753-a877-94a9c2f1fb72', 'dac7878f-8c46-44f8-abe1-adacb5a8bd29', 'Sine and Cosine Rules', 'text', '{"html": "\n                                <h3>Sine Rule</h3>\n                                <p>Use for non-right-angled triangles with matching pairs of angle/side.</p>\n                                \\[ \\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C} \\]\n                                <h3>Cosine Rule</h3>\n                                <p>Use when you have SAS (Side-Angle-Side) or SSS (Side-Side-Side).</p>\n                                \\[ a^2 = b^2 + c^2 - 2bc \\cos A \\]\n                                <p>Rearranged for angle:</p>\n                                \\[ \\cos A = \\frac{b^2 + c^2 - a^2}{2bc} \\]\n                            ", "blocks": [{"id": "38f77fd7-1f24-4598-8d57-8006cb355168", "type": "text", "content": "\n                                <h3>Sine Rule</h3>\n                                <p>Use for non-right-angled triangles with matching pairs of angle/side.</p>\n                                \\[ \\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C} \\]\n                                <h3>Cosine Rule</h3>\n                                <p>Use when you have SAS (Side-Angle-Side) or SSS (Side-Side-Side).</p>\n                                \\[ a^2 = b^2 + c^2 - 2bc \\cos A \\]\n                                <p>Rearranged for angle:</p>\n                                \\[ \\cos A = \\frac{b^2 + c^2 - a^2}{2bc} \\]\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('3b5d650e-b7fe-4604-9ccf-642c79fcbae0', 'dac7878f-8c46-44f8-abe1-adacb5a8bd29', 'Area of a Triangle', 'text', '{"html": "\n                                <h3>Formula</h3>\n                                <p>Area = \\( \\frac{1}{2}ab \\sin C \\)</p>\n                                <p>Where C is the included angle between sides a and b.</p>\n                            ", "blocks": [{"id": "870d63ee-74e2-426f-bec0-e6a743057152", "type": "text", "content": "\n                                <h3>Formula</h3>\n                                <p>Area = \\( \\frac{1}{2}ab \\sin C \\)</p>\n                                <p>Where C is the included angle between sides a and b.</p>\n                            ", "order": 0}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('dc9977b2-09a6-4d4a-9b85-179d330d4a78', '5422b24e-1acc-4c1d-bb87-4d291296546a', 'Vectors', 2, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('52077883-c1bc-440e-bd3b-659400db992e', 'dc9977b2-09a6-4d4a-9b85-179d330d4a78', 'Introduction to Vectors', 'text', '{"html": "\n                                <h3>Scalars vs Vectors</h3>\n                                <p>A scalar has magnitude only. A vector has both magnitude and direction.</p>\n                                <h3>Column Vectors</h3>\n                                <p>Represented as \\( \\mathbf{v} = \\begin{pmatrix} x \\\\ y \\end{pmatrix} \\).</p>\n                                <h3>Magnitude</h3>\n                                \\[ |\\mathbf{v}| = \\sqrt{x^2 + y^2} \\]\n                                <h3>Vector Addition</h3>\n                                \\[ \\begin{pmatrix} a \\\\ b \\end{pmatrix} + \\begin{pmatrix} c \\\\ d \\end{pmatrix} = \\begin{pmatrix} a+c \\\\ b+d \\end{pmatrix} \\]\n                            ", "blocks": [{"id": "1cb43977-005f-4909-bd4f-f4717877e2a0", "type": "text", "content": "\n                                <h3>Scalars vs Vectors</h3>\n                                <p>A scalar has magnitude only. A vector has both magnitude and direction.</p>\n                                <h3>Column Vectors</h3>\n                                <p>Represented as \\( \\mathbf{v} = \\begin{pmatrix} x \\\\ y \\end{pmatrix} \\).</p>\n                                <h3>Magnitude</h3>\n                                \\[ |\\mathbf{v}| = \\sqrt{x^2 + y^2} \\]\n                                <h3>Vector Addition</h3>\n                                \\[ \\begin{pmatrix} a \\\\ b \\end{pmatrix} + \\begin{pmatrix} c \\\\ d \\end{pmatrix} = \\begin{pmatrix} a+c \\\\ b+d \\end{pmatrix} \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('c8956387-1381-4c50-b7e2-dc12e4b700a9', '5422b24e-1acc-4c1d-bb87-4d291296546a', 'Mensuration', 3, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('81b0c18c-64d7-48ae-8f4e-0460642cdebd', 'c8956387-1381-4c50-b7e2-dc12e4b700a9', 'Area and Perimeter', 'text', '{"html": "\n                                <h3>Common Shapes</h3>\n                                <ul>\n                                    <li>Rectangle: Area = \\( l \\times w \\)</li>\n                                    <li>Triangle: Area = \\( \\frac{1}{2}bh \\)</li>\n                                    <li>Trapezium: Area = \\( \\frac{1}{2}(a+b)h \\)</li>\n                                    <li>Circle: Area = \\( \\pi r^2 \\), Circumference = \\( 2\\pi r \\)</li>\n                                </ul>\n                            ", "blocks": [{"id": "323f6e4f-b724-4d15-b28f-5635a03425dc", "type": "text", "content": "\n                                <h3>Common Shapes</h3>\n                                <ul>\n                                    <li>Rectangle: Area = \\( l \\times w \\)</li>\n                                    <li>Triangle: Area = \\( \\frac{1}{2}bh \\)</li>\n                                    <li>Trapezium: Area = \\( \\frac{1}{2}(a+b)h \\)</li>\n                                    <li>Circle: Area = \\( \\pi r^2 \\), Circumference = \\( 2\\pi r \\)</li>\n                                </ul>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('737f8808-8b05-4882-b282-0c54105a9baf', 'c8956387-1381-4c50-b7e2-dc12e4b700a9', 'Volume and Surface Area', 'text', '{"html": "\n                                <h3>3D Shapes</h3>\n                                <ul>\n                                    <li>Cylinder Volume = \\( \\pi r^2 h \\)</li>\n                                    <li>Cone Volume = \\( \\frac{1}{3}\\pi r^2 h \\)</li>\n                                    <li>Sphere Volume = \\( \\frac{4}{3}\\pi r^3 \\)</li>\n                                    <li>Sphere Surface Area = \\( 4\\pi r^2 \\)</li>\n                                </ul>\n                            ", "blocks": [{"id": "f927f78a-8eb3-46e5-8c7c-677e91b671c6", "type": "text", "content": "\n                                <h3>3D Shapes</h3>\n                                <ul>\n                                    <li>Cylinder Volume = \\( \\pi r^2 h \\)</li>\n                                    <li>Cone Volume = \\( \\frac{1}{3}\\pi r^2 h \\)</li>\n                                    <li>Sphere Volume = \\( \\frac{4}{3}\\pi r^3 \\)</li>\n                                    <li>Sphere Surface Area = \\( 4\\pi r^2 \\)</li>\n                                </ul>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('2ca0643c-e65c-489e-9628-691c5caa4a05', '5422b24e-1acc-4c1d-bb87-4d291296546a', 'Bearings', 4, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('a75da3fd-5b93-48bb-93fc-4d7129bc2d51', '2ca0643c-e65c-489e-9628-691c5caa4a05', 'Understanding Bearings', 'text', '{"html": "\n                                <h3>Three Rules</h3>\n                                <ol>\n                                    <li>Measure from North.</li>\n                                    <li>Measure clockwise.</li>\n                                    <li>Always use 3 digits (e.g., 045\u00b0).</li>\n                                </ol>\n                                <h3>Example</h3>\n                                <p>The bearing of B from A is 060\u00b0. Find the bearing of A from B.</p>\n                                <p>Solution: Add 180\u00b0 to return.</p>\n                                \\[ 060 + 180 = 240^\\circ \\]\n                            ", "blocks": [{"id": "2388da9b-205b-49c4-8486-e5e320c6e395", "type": "text", "content": "\n                                <h3>Three Rules</h3>\n                                <ol>\n                                    <li>Measure from North.</li>\n                                    <li>Measure clockwise.</li>\n                                    <li>Always use 3 digits (e.g., 045\u00b0).</li>\n                                </ol>\n                                <h3>Example</h3>\n                                <p>The bearing of B from A is 060\u00b0. Find the bearing of A from B.</p>\n                                <p>Solution: Add 180\u00b0 to return.</p>\n                                \\[ 060 + 180 = 240^\\circ \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
