('19ec4296-bab5-49f8-9483-981abe071b83', 'ca03c700-96c1-4746-977c-aadc8797565d', 'Differentiation', 0, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('b4fc419f-7dc8-48fe-b6a1-e8cdcc784e5c', '19ec4296-bab5-49f8-9483-981abe071b83', 'First Principles', 'text', '{"html": "\n                                <h3>Definition</h3>\n                                <p>The derivative is defined as the limit of the gradient of the chord:</p>\n                                \\[ f''(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h} \\]\n                                <h3>Power Rule</h3>\n                                <p>If \\( y = ax^n \\), then:</p>\n                                \\[ \\frac{dy}{dx} = anx^{n-1} \\]\n                                <p>Example: Differentiate \\( y = 3x^4 \\).</p>\n                                \\[ \\frac{dy}{dx} = 3(4)x^{3} = 12x^3 \\]\n                            ", "blocks": [{"id": "b324de88-e999-4681-9280-dda33c795196", "type": "text", "content": "\n                                <h3>Definition</h3>\n                                <p>The derivative is defined as the limit of the gradient of the chord:</p>\n                                \\[ f''(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h} \\]\n                                <h3>Power Rule</h3>\n                                <p>If \\( y = ax^n \\), then:</p>\n                                \\[ \\frac{dy}{dx} = anx^{n-1} \\]\n                                <p>Example: Differentiate \\( y = 3x^4 \\).</p>\n                                \\[ \\frac{dy}{dx} = 3(4)x^{3} = 12x^3 \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('f25c6e6d-97fc-47ed-80ad-5cf7bfb7aa30', '19ec4296-bab5-49f8-9483-981abe071b83', 'Tangents and Normals', 'text', '{"html": "\n                                <h3>Tangent</h3>\n                                <p>The gradient of the tangent is \\( m_t = \\frac{dy}{dx} \\) at that point.</p>\n                                <h3>Normal</h3>\n                                <p>The normal is perpendicular to the tangent, so its gradient is:</p>\n                                \\[ m_n = -\\frac{1}{m_t} \\]\n                                <h3>Example</h3>\n                                <p>Find tangent to \\( y = x^2 \\) at \\( x = 1 \\).</p>\n                                <p>\\( \\frac{dy}{dx} = 2x \\). At \\( x=1 \\), \\( m=2 \\). Point (1, 1).</p>\n                                <p>Eq: \\( y - 1 = 2(x - 1) \\implies y = 2x - 1 \\).</p>\n                            ", "blocks": [{"id": "b3197aea-4d24-4d40-bed8-9874594a236e", "type": "text", "content": "\n                                <h3>Tangent</h3>\n                                <p>The gradient of the tangent is \\( m_t = \\frac{dy}{dx} \\) at that point.</p>\n                                <h3>Normal</h3>\n                                <p>The normal is perpendicular to the tangent, so its gradient is:</p>\n                                \\[ m_n = -\\frac{1}{m_t} \\]\n                                <h3>Example</h3>\n                                <p>Find tangent to \\( y = x^2 \\) at \\( x = 1 \\).</p>\n                                <p>\\( \\frac{dy}{dx} = 2x \\). At \\( x=1 \\), \\( m=2 \\). Point (1, 1).</p>\n                                <p>Eq: \\( y - 1 = 2(x - 1) \\implies y = 2x - 1 \\).</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('a4295654-0a39-4c0f-a5da-c6dfd8ba77d9', '19ec4296-bab5-49f8-9483-981abe071b83', 'Chain, Product, Quotient Rules', 'text', '{"html": "\n                                <h3>Chain Rule</h3>\n                                <p>Function of a function:</p>\n                                \\[ \\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} \\]\n                                <h3>Product Rule</h3>\n                                <p>For \\( y = uv \\):</p>\n                                \\[ \\frac{dy}{dx} = u\\frac{dv}{dx} + v\\frac{du}{dx} \\]\n                                <h3>Quotient Rule</h3>\n                                <p>For \\( y = \\frac{u}{v} \\):</p>\n                                \\[ \\frac{dy}{dx} = \\frac{v\\frac{du}{dx} - u\\frac{dv}{dx}}{v^2} \\]\n                            ", "blocks": [{"id": "344c3b74-4a62-4310-9d6b-0d157d64d8f9", "type": "text", "content": "\n                                <h3>Chain Rule</h3>\n                                <p>Function of a function:</p>\n                                \\[ \\frac{dy}{dx} = \\frac{dy}{du} \\times \\frac{du}{dx} \\]\n                                <h3>Product Rule</h3>\n                                <p>For \\( y = uv \\):</p>\n                                \\[ \\frac{dy}{dx} = u\\frac{dv}{dx} + v\\frac{du}{dx} \\]\n                                <h3>Quotient Rule</h3>\n                                <p>For \\( y = \\frac{u}{v} \\):</p>\n                                \\[ \\frac{dy}{dx} = \\frac{v\\frac{du}{dx} - u\\frac{dv}{dx}}{v^2} \\]\n                            ", "order": 0}]}', 2, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('4a5d742b-dd0f-47b3-941a-b5f4a6413592', 'ca03c700-96c1-4746-977c-aadc8797565d', 'Integration', 1, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('e8cd7e22-c4c4-4479-a3cb-76d9b0a98581', '4a5d742b-dd0f-47b3-941a-b5f4a6413592', 'Indefinite Integration', 'text', '{"html": "\n                                <h3>Reverse of Differentiation</h3>\n                                <p>If \\( \\frac{dy}{dx} = ax^n \\), then:</p>\n                                \\[ y = \\int ax^n \\, dx = \\frac{ax^{n+1}}{n+1} + C \\]\n                                <p><strong>Don''t forget the constant of integration +C!</strong></p>\n                                <h3>Example</h3>\n                                <p>Integrate \\( 3x^2 \\).</p>\n                                \\[ \\int 3x^2 \\, dx = \\frac{3x^3}{3} + C = x^3 + C \\]\n                            ", "blocks": [{"id": "f7e0da6f-ae76-4d0e-8369-1f4d83091b67", "type": "text", "content": "\n                                <h3>Reverse of Differentiation</h3>\n                                <p>If \\( \\frac{dy}{dx} = ax^n \\), then:</p>\n                                \\[ y = \\int ax^n \\, dx = \\frac{ax^{n+1}}{n+1} + C \\]\n                                <p><strong>Don''t forget the constant of integration +C!</strong></p>\n                                <h3>Example</h3>\n                                <p>Integrate \\( 3x^2 \\).</p>\n                                \\[ \\int 3x^2 \\, dx = \\frac{3x^3}{3} + C = x^3 + C \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('23b40f4e-e948-4ba7-a66e-fed4396e3d8b', '4a5d742b-dd0f-47b3-941a-b5f4a6413592', 'Definite Integration', 'text', '{"html": "\n                                <h3>Finding Area</h3>\n                                <p>The area under a curve between \\( x=a \\) and \\( x=b \\) is:</p>\n                                \\[ \\int_a^b f(x) \\, dx = [F(x)]_a^b = F(b) - F(a) \\]\n                                <h3>Example</h3>\n                                <p>Find area under \\( y = 2x \\) from 0 to 2.</p>\n                                \\[ \\int_0^2 2x \\, dx = [x^2]_0^2 = 2^2 - 0^2 = 4 \\]\n                            ", "blocks": [{"id": "bcaac76b-2f24-4832-8b15-8504a82e58c9", "type": "text", "content": "\n                                <h3>Finding Area</h3>\n                                <p>The area under a curve between \\( x=a \\) and \\( x=b \\) is:</p>\n                                \\[ \\int_a^b f(x) \\, dx = [F(x)]_a^b = F(b) - F(a) \\]\n                                <h3>Example</h3>\n                                <p>Find area under \\( y = 2x \\) from 0 to 2.</p>\n                                \\[ \\int_0^2 2x \\, dx = [x^2]_0^2 = 2^2 - 0^2 = 4 \\]\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('3219de61-69ef-46c7-aa0f-b6424eb90d61', 'ca03c700-96c1-4746-977c-aadc8797565d', 'Applications', 2, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('706631ab-19dc-45df-b1f5-0b6f92af0b92', '3219de61-69ef-46c7-aa0f-b6424eb90d61', 'Stationary Points', 'text', '{"html": "\n                                <h3>Finding Maxima and Minima</h3>\n                                <p>At a stationary point, \\( \\frac{dy}{dx} = 0 \\).</p>\n                                <h3>Nature of Point</h3>\n                                <ul>\n                                    <li>Find second derivative \\( \\frac{d^2y}{dx^2} \\).</li>\n                                    <li>If \\( > 0 \\): Minimum.</li>\n                                    <li>If \\( < 0 \\): Maximum.</li>\n                                    <li>If \\( = 0 \\): Point of Inflection (check gradients).</li>\n                                </ul>\n                            ", "blocks": [{"id": "7dd6fd9e-7715-4964-a93f-d02345ba34e2", "type": "text", "content": "\n                                <h3>Finding Maxima and Minima</h3>\n                                <p>At a stationary point, \\( \\frac{dy}{dx} = 0 \\).</p>\n                                <h3>Nature of Point</h3>\n                                <ul>\n                                    <li>Find second derivative \\( \\frac{d^2y}{dx^2} \\).</li>\n                                    <li>If \\( > 0 \\): Minimum.</li>\n                                    <li>If \\( < 0 \\): Maximum.</li>\n                                    <li>If \\( = 0 \\): Point of Inflection (check gradients).</li>\n                                </ul>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('cf10e954-981f-4174-a429-013892bcd621', 'ca03c700-96c1-4746-977c-aadc8797565d', 'Kinematics', 3, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('8efd26f0-b447-46a9-9e91-2c86d2af1dca', 'cf10e954-981f-4174-a429-013892bcd621', 'Displacement, Velocity, Acceleration', 'text', '{"html": "\n                                <h3>Relationships</h3>\n                                <ul>\n                                    <li>\\( v = \\frac{ds}{dt} \\) (Differentiate displacement)</li>\n                                    <li>\\( a = \\frac{dv}{dt} = \\frac{d^2s}{dt^2} \\) (Differentiate velocity)</li>\n                                </ul>\n                                <h3>Reverse</h3>\n                                <ul>\n                                    <li>\\( s = \\int v \\, dt \\)</li>\n                                    <li>\\( v = \\int a \\, dt \\)</li>\n                                </ul>\n                            ", "blocks": [{"id": "92be1e24-b85d-4f13-9bfc-bb9b57a9fdbe", "type": "text", "content": "\n                                <h3>Relationships</h3>\n                                <ul>\n                                    <li>\\( v = \\frac{ds}{dt} \\) (Differentiate displacement)</li>\n                                    <li>\\( a = \\frac{dv}{dt} = \\frac{d^2s}{dt^2} \\) (Differentiate velocity)</li>\n                                </ul>\n                                <h3>Reverse</h3>\n                                <ul>\n                                    <li>\\( s = \\int v \\, dt \\)</li>\n                                    <li>\\( v = \\int a \\, dt \\)</li>\n                                </ul>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO courses (id, title, description, created_by, status, visibility, level, language, price, created_at, updated_at) VALUES
('553d8ba2-d70c-4f4e-9c8c-3688dff084fc', 'A Level Mathematics: Probability & Statistics', 'Statistical analysis, representation of data, and probability theory.', (SELECT id FROM users WHERE email = 'admin@test.com' LIMIT 1), 'published', 'public', 'advanced', 'en', 0, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('5cd23775-2b74-4b31-a008-477b13b1de97', '553d8ba2-d70c-4f4e-9c8c-3688dff084fc', 'Representation of Data', 0, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('8c8997fe-ae33-4415-b669-00b5e080a186', '5cd23775-2b74-4b31-a008-477b13b1de97', 'Histograms', 'text', '{"html": "\n                                <h3>Frequency Density</h3>\n                                <p>In a histogram, area represents frequency.</p>\n                                \\[ \\text{Frequency Density} = \\frac{\\text{Frequency}}{\\text{Class Width}} \\]\n                                <p>The height of the bar is the frequency density.</p>\n                            ", "blocks": [{"id": "5ed3fb89-1aa9-40f4-a431-bb9d6790937d", "type": "text", "content": "\n                                <h3>Frequency Density</h3>\n                                <p>In a histogram, area represents frequency.</p>\n                                \\[ \\text{Frequency Density} = \\frac{\\text{Frequency}}{\\text{Class Width}} \\]\n                                <p>The height of the bar is the frequency density.</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('f488ee4b-b000-44ce-bb9e-2326ca3497db', '5cd23775-2b74-4b31-a008-477b13b1de97', 'Averages and Spread', 'text', '{"html": "\n                                <h3>Measures of Location</h3>\n                                <ul>\n                                    <li>Mean \\( \\bar{x} = \\frac{\\sum x}{n} \\)</li>\n                                    <li>Median: Middle value.</li>\n                                    <li>Mode: Most common value.</li>\n                                </ul>\n                                <h3>Measures of Spread</h3>\n                                <ul>\n                                    <li>Range = Max - Min</li>\n                                    <li>Variance \\( \\sigma^2 = \\frac{\\sum x^2}{n} - \\bar{x}^2 \\)</li>\n                                    <li>Standard Deviation \\( \\sigma = \\sqrt{\\text{Variance}} \\)</li>\n                                </ul>\n                            ", "blocks": [{"id": "6b5d692c-9b4f-4dc2-9cd5-f3977fe6db8d", "type": "text", "content": "\n                                <h3>Measures of Location</h3>\n                                <ul>\n                                    <li>Mean \\( \\bar{x} = \\frac{\\sum x}{n} \\)</li>\n                                    <li>Median: Middle value.</li>\n                                    <li>Mode: Most common value.</li>\n                                </ul>\n                                <h3>Measures of Spread</h3>\n                                <ul>\n                                    <li>Range = Max - Min</li>\n                                    <li>Variance \\( \\sigma^2 = \\frac{\\sum x^2}{n} - \\bar{x}^2 \\)</li>\n                                    <li>Standard Deviation \\( \\sigma = \\sqrt{\\text{Variance}} \\)</li>\n                                </ul>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('1675975b-f77d-4ffb-9522-520a5dbc3ce4', '553d8ba2-d70c-4f4e-9c8c-3688dff084fc', 'Probability', 1, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('94c121d9-f932-4dd6-9766-681366266068', '1675975b-f77d-4ffb-9522-520a5dbc3ce4', 'Basic Probability', 'text', '{"html": "\n                                <h3>Formulas</h3>\n                                <p>\\( P(A) = \\frac{\\text{Number of successful outcomes}}{\\text{Total outcomes}} \\)</p>\n                                <p>\\( P(A'') = 1 - P(A) \\)</p>\n                                <h3>Combined Events</h3>\n                                <p><strong>Independent:</strong> \\( P(A \\cap B) = P(A) \\times P(B) \\)</p>\n                                <p><strong>Mutually Exclusive:</strong> \\( P(A \\cup B) = P(A) + P(B) \\)</p>\n                            ", "blocks": [{"id": "e31ff397-0273-41a2-b9d4-99858a314bd3", "type": "text", "content": "\n                                <h3>Formulas</h3>\n                                <p>\\( P(A) = \\frac{\\text{Number of successful outcomes}}{\\text{Total outcomes}} \\)</p>\n                                <p>\\( P(A'') = 1 - P(A) \\)</p>\n                                <h3>Combined Events</h3>\n                                <p><strong>Independent:</strong> \\( P(A \\cap B) = P(A) \\times P(B) \\)</p>\n                                <p><strong>Mutually Exclusive:</strong> \\( P(A \\cup B) = P(A) + P(B) \\)</p>\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('9b4debeb-e37c-4ec9-9d4f-e5657b54bb76', '1675975b-f77d-4ffb-9522-520a5dbc3ce4', 'Conditional Probability', 'text', '{"html": "\n                                <h3>Formula</h3>\n                                \\[ P(A|B) = \\frac{P(A \\cap B)}{P(B)} \\]\n                                <p>Probability of A given B has happened.</p>\n                            ", "blocks": [{"id": "c5518c61-49d8-49a3-9b52-97b836a5f22d", "type": "text", "content": "\n                                <h3>Formula</h3>\n                                \\[ P(A|B) = \\frac{P(A \\cap B)}{P(B)} \\]\n                                <p>Probability of A given B has happened.</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
INSERT INTO course_modules (id, course_id, title, order_index, created_at, updated_at) VALUES
('2ebe9e1d-e694-42d3-a975-947d76e2a5df', '553d8ba2-d70c-4f4e-9c8c-3688dff084fc', 'Probability Distributions', 2, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('f50ed0da-57e7-4766-80a8-dab522a91aae', '2ebe9e1d-e694-42d3-a975-947d76e2a5df', 'Binomial Distribution', 'text', '{"html": "\n                                <h3>Conditions</h3>\n                                <ul>\n                                    <li>Fixed number of trials (n).</li>\n                                    <li>Two outcomes (Success/Failure).</li>\n                                    <li>Constant probability of success (p).</li>\n                                    <li>Independent trials.</li>\n                                </ul>\n                                <h3>Formula</h3>\n                                \\[ P(X=r) = \\binom{n}{r} p^r (1-p)^{n-r} \\]\n                            ", "blocks": [{"id": "487158ee-a826-4fa6-b5e5-6fc2cb82c22f", "type": "text", "content": "\n                                <h3>Conditions</h3>\n                                <ul>\n                                    <li>Fixed number of trials (n).</li>\n                                    <li>Two outcomes (Success/Failure).</li>\n                                    <li>Constant probability of success (p).</li>\n                                    <li>Independent trials.</li>\n                                </ul>\n                                <h3>Formula</h3>\n                                \\[ P(X=r) = \\binom{n}{r} p^r (1-p)^{n-r} \\]\n                            ", "order": 0}]}', 0, true, 15, NOW(), NOW());
INSERT INTO course_lessons (id, module_id, title, content_type, content_data, order_index, is_published, duration_minutes, created_at, updated_at) VALUES
('16b28733-b31c-4ebd-8c24-fdd3d4a6b95d', '2ebe9e1d-e694-42d3-a975-947d76e2a5df', 'Normal Distribution', 'text', '{"html": "\n                                <h3>Bell Curve</h3>\n                                <p>Symmetric about the mean \\( \\mu \\).</p>\n                                <h3>Standard Normal Variable Z</h3>\n                                \\[ Z = \\frac{X - \\mu}{\\sigma} \\]\n                                <p>Use tables to find probabilities for \\( Z \\).</p>\n                            ", "blocks": [{"id": "53a29f54-ebca-4bf5-a9e5-244bb56bfb7a", "type": "text", "content": "\n                                <h3>Bell Curve</h3>\n                                <p>Symmetric about the mean \\( \\mu \\).</p>\n                                <h3>Standard Normal Variable Z</h3>\n                                \\[ Z = \\frac{X - \\mu}{\\sigma} \\]\n                                <p>Use tables to find probabilities for \\( Z \\).</p>\n                            ", "order": 0}]}', 1, true, 15, NOW(), NOW());
